function Node:soft(k)
    k = k or 0
    if k == (self.sk or 0) then return self end
    local was = self.sk or 0
    self.sk = k
    N.size = N.size + 1
    local c = self.c
    safe(function()
        if k > 0 then
            if was == 0 then
                c.enableMask = true
                c.enableSoftEdge = true
