            self:setState(p, 'down'); p.vx = 0
            self:emit({type = 'land', p = p.id, hard = true, x = p.x})
            return
        end
        self:setState(p, 'down')
        p.vx = p.vx // 3
        self:emit({type = 'land', p = p.id, hard = true, x = p.x})
